-- V8.6 full workbook coverage. Run after the existing migrations through 015.
-- Works with or without V8.4 additions; does not replace approved targets or remove rows.
begin;
lock table public.parameter_master in share row exclusive mode;
create or replace function pg_temp.svma_name(t text) returns text language sql immutable as $$ select regexp_replace(upper(coalesce(t,'')), '[^A-Z0-9]', '', 'g') $$;
create or replace function pg_temp.svma_section(t text) returns text language sql immutable as $$ select pg_temp.svma_name(replace(regexp_replace(upper(t),'^[A-Z]\)\s*',''),'VESION','VISION')) $$;
create temporary table svma_v86_source(row_no integer, module text, section_name text, serial text, name text, target text, input_type text, frequency text, aliases jsonb) on commit drop;

select module,section_name,min(row_no),true from svma_v86_source v
where not exists(select 1 from public.parameter_sections s where s.module=v.module and pg_temp.svma_section(s.name)=pg_temp.svma_section(v.section_name)) group by module,section_name;
create temporary table svma_v86_sections on commit drop as
select v.row_no,(select s.id from public.parameter_sections s where s.module=v.module and pg_temp.svma_section(s.name)=pg_temp.svma_section(v.section_name) order by s.active desc,s.id limit 1) section_id from svma_v86_source v;
create temporary table svma_v86_matches on commit drop as
select distinct on (v.row_no) v.row_no,p.id parameter_id from svma_v86_source v join public.parameter_sections s on s.module=v.module and pg_temp.svma_section(s.name)=pg_temp.svma_section(v.section_name)
join public.parameter_master p on p.section_id=s.id where
pg_temp.svma_name(p.name)=pg_temp.svma_name(v.name)
or exists(select 1 from jsonb_array_elements_text(v.aliases) a where pg_temp.svma_name(p.name)=pg_temp.svma_name(a.value))
order by v.row_no,p.active desc,p.id;
-- Insert only genuinely absent source rows. Original target corrections remain intact.
select s.section_id,'AGRO_COMPLETE_V86:R'||v.row_no,'AGRO SAFETY POINTS.xlsx',v.serial,
case when v.frequency='hourly' then 'Readings' else 'Shift checks' end,v.name,v.name,v.target,v.input_type,v.frequency,
case when v.input_type='select' then '["OK","NOT OK"]'::jsonb else '[]'::jsonb end,v.row_no,true,
case when v.frequency='first_shift_only' then '[1]'::jsonb else '[1,2,3]'::jsonb end,'PLANT',true,true,true
from svma_v86_source v join svma_v86_sections s using(row_no) where not exists(select 1 from svma_v86_matches m where m.row_no=v.row_no);
-- Existing identities, names, numeric limits and approved targets are retained.
update public.parameter_master p set active=true,alert_enabled=true,ticket_enabled=true,
frequency=case when v.frequency='hourly' or p.frequency in ('hourly','every_two_hours','every_4_hours') then 'hourly' else v.frequency end,
input_type=case when v.input_type='number' then 'number' else p.input_type end
from svma_v86_matches m join svma_v86_source v using(row_no) where p.id=m.parameter_id;
update public.parameter_sections s set active=true where s.id in(select section_id from svma_v86_sections);
-- All interval readings are now available once per hour; Finance and Quality unchanged.
update public.parameter_master p set frequency='hourly' from public.parameter_sections s where p.section_id=s.id and s.module in('solvent','boiler') and p.active and p.frequency in('every_two_hours','every_4_hours');
-- Hide exact duplicate display rows only; never merge different targets.
with ranked as (select p.id,row_number() over(partition by s.module,pg_temp.svma_section(s.name),pg_temp.svma_name(p.name),coalesce(p.target_text,''),p.frequency,p.input_type order by p.id) n
from public.parameter_master p join public.parameter_sections s on s.id=p.section_id where p.active and s.module in ('solvent','boiler'))
update public.parameter_master p set active=false from ranked r where p.id=r.id and r.n>1;
-- A source-to-parameter ledger proves coverage in the actual installation.
create table if not exists public.safety_source_coverage(source_row integer primary key,parameter_id bigint not null references public.parameter_master(id),source_name text not null,source_section text not null);
alter table public.safety_source_coverage enable row level security;
select v.row_no,coalesce((select min(m.parameter_id) from svma_v86_matches m where m.row_no=v.row_no),(select min(p.id) from public.parameter_master p where p.source_ref='AGRO_COMPLETE_V86:R'||v.row_no)),v.name,v.section_name from svma_v86_source v
on conflict(source_row) do update set parameter_id=excluded.parameter_id,source_name=excluded.source_name,source_section=excluded.source_section;
do $$ begin
 if (select count(distinct c.parameter_id) from public.safety_source_coverage c join public.parameter_master p on p.id=c.parameter_id where p.active) <> 453 then raise exception 'Workbook coverage is incomplete; upgrade rolled back'; end if;
end $$;
select c.source_section,count(*) workbook_points,count(*) filter(where p.frequency='hourly') hourly_points,count(*) filter(where p.frequency<>'hourly') shift_points from public.safety_source_coverage c join public.parameter_master p on p.id=c.parameter_id group by c.source_section order by min(c.source_row);

-- Persist deviation, ticket and notifications in the same transaction as the reading.
create unique index if not exists notifications_dedupe_v86_uq on public.notifications(dedupe_key);
create or replace function public.svma_saved_reading_alert() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare p record; scope_name text; deviation_id uuid; fact text;
begin
 if new.validation_status not in ('warning','critical') then return new; end if;
 select pm.*,s.module,s.name section_name into p from public.parameter_master pm join public.parameter_sections s on s.id=pm.section_id where pm.id=new.parameter_id;
 if p.module not in ('solvent','boiler','quality') then return new; end if;
 scope_name:=case when p.module='quality' then 'quality' else 'solvent' end;
 fact:=p.section_name||' · '||p.name||': actual '||coalesce(new.value_numeric::text,new.value_text,'')||'; target '||coalesce(new.expected_target,'');
 values(new.id,new.shift_session_id,new.parameter_id,new.validation_status,new.expected_target,coalesce(new.value_numeric::text,new.value_text,''),'open',jsonb_build_array(fact)) returning id into deviation_id;
 values('SVMA-'||case when scope_name='quality' then 'QC-' else 'SOL-' end||replace(new.id::text,'-',''),deviation_id,'open',now()+interval '2 hours');
 select recipients.user_id,scope_name||'_parameter_deviation',upper(new.validation_status)||' · '||p.name,fact,new.validation_status,'deviation',deviation_id::text,'deviation:'||new.id::text||':'||recipients.user_id::text
 from (select new.entered_by user_id union select ur.user_id from public.user_roles ur where ur.role::text in ('super_admin','admin','management','ceo','solvent_head') or (scope_name='quality' and ur.role::text='quality_head')) recipients
 where recipients.user_id is not null on conflict(dedupe_key) do nothing;
 return new;
end $$;
revoke all on function public.svma_saved_reading_alert() from public;
drop trigger if exists svma_saved_reading_alert on public.parameter_entries;
create trigger svma_saved_reading_alert after insert on public.parameter_entries for each row execute function public.svma_saved_reading_alert();
-- Enable the existing user-scoped notification stream, if the publication exists.
do $$ begin
 if exists(select 1 from pg_publication where pubname='supabase_realtime') and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='notifications') then
  alter publication supabase_realtime add table public.notifications;
 end if;
end $$;
commit;
